def write():
    counts=[]
    for s in STORIES:
        assert len(s['parts']) == len(s['shots']) == 8
        words=len(re.findall(r"\b[\w]+(?:['’][\w]+)*\b",' '.join(s['parts'])))
        assert 120 <= words <= 140,(s['slug'],words)
        day=s['day']; n=sum(x['day']==day for x in STORIES[:STORIES.index(s)+1]); eid=f'W01-D{day:02d}-E{n:02d}'
        folder=ROOT/'production'/'week-01'/f'day-{day:02d}';folder.mkdir(parents=True,exist_ok=True)
        title_options=[s['title'],f"Jason & Lucia: {s['title']}",f"The Price of {s['title'].removeprefix('The ')}"]
        setinfo=f"{s['set']}; original fan-fiction set, not a claimed game location."
        baseline=f"Continuous humid storm-night rain, amber practical key from frame left, teal wet reflections; no unexplained weather or time change. {s['wardrobe']}. Props: {s['prop']}. Both heroes are on foot except any explicitly stationary pictured vehicle. No extra vehicle occupants; all unseen seats remain empty. Supporting extras are anonymous one-episode figures."
        if s['slug']=='borrowed-sunset':baseline=baseline.replace('Continuous humid storm-night rain','Continuous humid tropical storm-dusk rain with fading orange offshore light')
        if s['slug']=='white-line': baseline += ' Charcoal four-door sedan, black five-spoke rims, all four tires contact dry pavement; Jason driver/Lucia front passenger only before exit; parked and empty thereafter.'
        if s['slug']=='wet-paint': baseline += ' Cream two-door coupe with exactly one blue driver door, silver six-spoke wheels, all tires on courtyard pavement; stationary engine off, no occupants throughout.'
        scenes=[]
        for i,(part,shot) in enumerate(zip(s['parts'],s['shots'])):
            final_light=' Any sunrise, dawn or next-day change occurs only when this scene explicitly calls for it; retain wardrobe and props across that transition.'
            amb='Wide soft tropical rain with close roof drips and far insect bed' if day==3 else 'Wide soft port rain, low distant harbor machinery and wet street hiss'
            if day==2:amb='Soft saltwater chop, tropical rain on nearby shelter roof, light coastal wind; distant coastal road hiss only where a street is shown'
            if 'inside' in shot or 'booth' in shot or 'lobby' in shot: amb='Filtered rain outside walls, low enclosed room tone, distant exterior sounds softened'
            sfx=DETAILS[s['slug']][2][i]+'; precisely aligned to visible action, quiet beneath speech'
            scenes.append(dict(start=i*7,end=(i+1)*7,narration=part,visual_prompt=STYLE+f"Use approved Jason and Lucia face references first; preserve exact identity/hair/build from references, check new boards against them. Set: {setinfo} Composition/action: {shot}. Wardrobe/continuity: {baseline}"+final_light+' Keep central faces and clue clear in middle 70%; reserve lower 20% for captions. No duplicate heroes or props. Still illustration with editorial camera motion; no lip-sync claim.',camera=CAMERAS[i],sound=dict(score=MUSIC[i],ambience=amb,sfx=sfx,mix='Centered dry speech anchors mix; all backgrounds duck about 14 dB below active speech; no SFX over consonants; music breathes only in pauses.'),continuity=dict(location=setinfo,wardrobe=s['wardrobe'],prop_state=shot,vehicle_occupants='No occupied vehicle unless explicitly shown; see episode baseline',entry_exit='Preserve left-to-right action established in scene 1; scene action states any move',reference_assets=REFS,light_weather=baseline.split(' Props:')[0]),on_screen_text=s['title'] if i==0 else ('FAN FICTION' if i==7 else '')))
        elapsed=0
        for i,sc in enumerate(scenes):
            segment_words=len(re.findall(r"\b[\w]+(?:['’][\w]+)*\b",sc['narration']))
            sc['start']=round(elapsed,2)
            elapsed+=55.5*segment_words/words
            sc['end']=56 if i==7 else round(elapsed,2)
        title_options=[s['title']]+DETAILS[s['slug']][0]
        alt=DETAILS[s['slug']][1]
        # Alternative hooks are optional replacements, never appended to the timed master.
        out=dict(id=eid,day=day,date=f'2026-11-{15+day:02d}',title=s['title'],title_options=title_options,duration_seconds=56,spoken_word_count=words,voice=dict(name=s['voice'],id='TX3LPaxmHKxFdv7VOQHJ' if s['voice']=='Liam' else 'FGY2WhTYpPnrIDTdsKH5',model='eleven_v4',settings=dict(stability=.5,similarity_boost=.75,style=.3,use_speaker_boost=True,speed=1.03),direction='Intimate, controlled storyteller; build curiosity without shouting; dry centered delivery; native pitch and tempo. Quoted character intent is performed by the same narrator; no extra voice.',licensing='Planning only; no generated audio. Existing free-plan review assets require release licensing resolution.'),timeline=s['timeline'],pov=s['pov'],delivery=s.get('delivery','narrator-led'),hook=s['parts'][0],alternative_hooks=alt,alternative_hook_use='Replace scene 1 and re-time/recount the master before production; do not append.',script=' '.join(s['parts']),plot_mechanism=s['mechanism'],story_relation='standalone; complete consequence and payoff',canon_status=dict(canonical_names=['Jason Duval','Lucia Caminos','Grassrivers' if day==3 else ('Leonida Keys' if day==2 else 'Port Gellhorn')],fictional_elements='All events, dialogue, sets, props, circumstances and supporting extras are original non-canon fan fiction; no game footage or official story claims.'),reference_assets=REFS,continuity_sheet=dict(baseline=baseline,scenes=[dict(scene=i+1,action=x,wardrobe=s['wardrobe'],prop=s['prop']) for i,x in enumerate(s['shots'])],review='Inspect reference identities, hand anatomy, prop grips/front-back orientation, unchanged wardrobe, unoccupied vehicle interiors, wheel contact and time of day at full size.'),cover=dict(text=s['title'].upper(),visual_prompt=STYLE+s['shots'][4]+'. Use the episode wardrobe and approved face references. Single clear clue and readable hero reaction, no collage; reserve top 25% for hand-added title.',safe_area='Keep text within center 80% width; no invented UI or official marks.'),upload_description=f"{s['title']} — an original GTA VI fan-fiction micro-story with Jason and Lucia, set around {('Grassrivers' if day==3 else ('Leonida Keys' if day==2 else 'Port Gellhorn'))}. This episode's specific set and events are invented, non-canon fan fiction. Unofficial and not affiliated with Rockstar Games. #GTAVI #FanFiction #ViceCityAlibis",scenes=scenes,production_notes=dict(captions='Add accurate sentence-level captions from script; max two short lines, high contrast, do not cover eyes or clue. On-screen text fields are edit overlays, never part of spoken word count.',timing='Eight contiguous windows apportioned to actual spoken word count, with a half-second final environmental tail. Fit each exact narration segment to its assigned window with natural pauses; audition after synthesis; do not pitch/tempo process approved voice. Full runtime 56 seconds.',audio_exports=['dry_voice','score','ducked_music','ambience','effects','full_mix'],provenance='Record API/model/settings/prompt/source/licensing per generated asset; none generated by this authoring pass.',publication='Production plan only. No upload or publication performed.'))
        if out['delivery']=='character dialogue':
            out['voice']['name']='Liam + Laura'
            out['voice']['id']='TX3LPaxmHKxFdv7VOQHJ / FGY2WhTYpPnrIDTdsKH5'
            out['voice']['direction']='Two distinct dry centered character performances: Liam as Jason, Laura as Lucia. Narration voices approved; these character castings are provisional and need performance listening review. No Lara substitution. Calm urgent turns; no overlap or lip-sync claim.'
            out['casting']={'status':'provisional character casting; narrator approvals do not approve impersonation','Jason':'Liam','Lucia':'Laura'}
            for i,sc in enumerate(scenes):
                speaker='Jason' if i%2==0 else 'Lucia'
                sc['speaker']=speaker
                sc['visual_prompt']+=f' Frame {speaker} as the speaking/reaction anchor, with the existing scene clue readable beside or behind them; no mouth animation.'
                sc['on_screen_text']=(sc['on_screen_text']+' | ' if sc['on_screen_text'] else '')+speaker
        if out['delivery']=='first-person confession':
            out['voice']['direction']='Intimate first-person confession by '+('Jason' if s['slug']=='borrowed-thunder' else 'Lucia')+'. Approved narrator voice, provisional character interpretation; preserve native pitch and tempo. Keep memory shifts clear and quiet.'
            out['casting']={'status':'provisional first-person character interpretation; listening review required'}
        stem=f'{n:02d}-{s["slug"]}';(folder/(stem+'.json')).write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
        md=[f'# {eid} — {s["title"]}',f'Date: {out["date"]} | 56 seconds | {words} spoken words | {out["voice"]["name"]}',f'\nTimeline: {s["timeline"]}. POV: {s["pov"]}. Delivery: {out["delivery"]}. Standalone payoff.',f'\nMechanism: {s["mechanism"]}.', '\n## Hook',s['parts'][0],'\nAlternative hooks (replace opening and re-time; never append):',*['- '+x for x in alt],'\n## Title options',*['- '+x for x in title_options],'\n## Full script',out['script'],'\n## Continuity',setinfo,baseline,'\nReference assets:',*['- '+x for x in REFS],'\n## Voice and mix',json.dumps(out['voice'],ensure_ascii=False,indent=2),'Speech centered and clear; duck backgrounds around 14 dB below active speech. Export dry voice, score, ducked music, ambience, effects and full mix separately. Audition exact segment fit without pitch/tempo processing.']
        for i,sc in enumerate(scenes):
            md += [f'\n## Scene {i+1} — {sc["start"]}–{sc["end"]} seconds',f'**Narration:** {sc["narration"]}',f'\n**Visual:** {sc["visual_prompt"]}',f'\n**Camera/motion:** {sc["camera"]}',f'\n**Sound:** Score: {sc["sound"]["score"]}. Ambience: {sc["sound"]["ambience"]}. SFX: {sc["sound"]["sfx"]}. {sc["sound"]["mix"]}',f'\n**Continuity state:** {sc["continuity"]["prop_state"]}. Maintain episode clothes, weather and source identity; change time only when stated.',f'\n**Text overlay:** {sc["on_screen_text"] or "Captions only"}.']
        md += ['\n## Cover',f'Text: {out["cover"]["text"]}',out['cover']['visual_prompt'],'\n## Upload description',out['upload_description'],'\n## Production review','All character faces follow existing approved references. Check hands, prop position, any visible vehicle contact and occupants at full size. No generated image, audio, account action or upload is included. Caption from exact script; alternative hooks require a new timing pass. Fictional sets and events are never presented as confirmed game content. Record provenance and clear release audio rights before commercial distribution.']
        (folder/(stem+'.md')).write_text('\n\n'.join(md)+'\n',encoding='utf-8');counts.append((eid,words))
    print(json.dumps(counts))

if __name__=='__main__':write()
